-- English translations for the seeded places and governorates. Safe to re-run (updates only; does not touch Arabic).
-- Run AFTER migration 20261022000000_english.sql and after the seed files.
begin;
update public.regions set name_en=$t$Amman$t$ where id='amman';
update public.regions set name_en=$t$Irbid$t$ where id='irbid';
update public.regions set name_en=$t$Zarqa$t$ where id='zarqa';
update public.regions set name_en=$t$Balqa$t$ where id='balqa';
update public.regions set name_en=$t$Madaba$t$ where id='madaba';
update public.regions set name_en=$t$Karak$t$ where id='karak';
update public.regions set name_en=$t$Tafilah$t$ where id='tafilah';
update public.regions set name_en=$t$Ma'an$t$ where id='maan';
update public.regions set name_en=$t$Aqaba$t$ where id='aqaba';
update public.regions set name_en=$t$Jerash$t$ where id='jerash';
update public.regions set name_en=$t$Ajloun$t$ where id='ajloun';
update public.regions set name_en=$t$Mafraq$t$ where id='mafraq';
update public.places set name_en=$t$Petra$t$, description_en=$t$An archaeological site carved into the rock between the Red Sea and the Dead Sea, and the capital of the Nabataeans. UNESCO describes it as half-built, half-carved into rock, surrounded by mountains crossed by passages and gorges. In the Hellenistic and Roman periods it was a major caravan center and crossroads between Arabia, Egypt and the Levant, and its water management system made settlement possible in a dry region. It was inscribed on the World Heritage List in 1985.$t$, region_name_en=$t$Ma'an$t$ where id='petra';
update public.places set name_en=$t$Wadi Rum Protected Area$t$, description_en=$t$A protected area in southern Jordan near the Saudi border, about 74,000 hectares, inscribed as a mixed natural and cultural World Heritage site in 2011. It has narrow gorges, natural arches and towering cliffs; rock carvings and ruins indicate some 12,000 years of human settlement, with about 25,000 rock carvings and 20,000 inscriptions.$t$, region_name_en=$t$Aqaba$t$ where id='wadi-rum';
update public.places set name_en=$t$Baptism Site (Bethany Beyond the Jordan)$t$, description_en=$t$An archaeological site on the east bank of the Jordan River, about nine kilometers north of the Dead Sea, believed to be where Jesus was baptized by John the Baptist. It contains Roman and Byzantine remains including churches, chapels, a monastery, hermit caves and baptism pools, and is a Christian pilgrimage site. It was inscribed on the World Heritage List in 2015.$t$, region_name_en=null where id='baptism-site-al-maghtas';
update public.places set name_en=$t$Quseir Amra$t$, description_en=$t$A desert castle in the eastern desert of Zarqa Governorate, built in the early 8th century CE as a fortress with a garrison and a residence for Umayyad caliphs. Its reception hall and bathhouse are decorated with figurative wall paintings that reflect the secular art of the era. Inscribed on the World Heritage List in 1985.$t$, region_name_en=$t$Zarqa$t$ where id='quseir-amra';
update public.places set name_en=$t$Um er-Rasas$t$, description_en=$t$An archaeological site southeast of Madaba on the edge of the semi-arid steppe, which began as a Roman military camp and became a town from the 5th century. It has a fortified Roman camp and 16 churches, some with well-preserved mosaic floors, including the Church of Saint Stephen, and two square towers thought to be the only remaining example of stylite (pillar-hermit) practice in the region. Most of the site is still unexcavated. Inscribed on the World Heritage List in 2004.$t$, region_name_en=null where id='um-er-rasas';
update public.places set name_en=$t$Jerash (Gerasa)$t$, description_en=$t$A city in northern Jordan and the center of Jerash Governorate, about 48 km north of Amman. Its ancient name is Gerasa, and it is nicknamed the "Pompeii of the Middle East". Its landmarks include the oval plaza with Ionic columns, the temples of Artemis and Zeus, the north and south theaters, the colonnaded street, Hadrian's Arch, the hippodrome, large public baths, a nymphaeum (fountain) and nearly complete city walls.$t$, region_name_en=$t$Jerash$t$ where id='jerash';
update public.places set name_en=$t$Amman Citadel (Jabal al-Qala'a)$t$, description_en=$t$An archaeological site on a hill overlooking downtown Amman, known in Arabic as "al-Qala'a". It is one of the oldest continuously inhabited places in the world and was the capital of the Kingdom of Ammon. Its landmarks include the great Roman temple (known as the Temple of Hercules), a 6th-century Byzantine church, the Umayyad Palace built by Caliph Hisham ibn Abd al-Malik, and the Jordan Archaeological Museum, founded in 1951.$t$, region_name_en=$t$Amman$t$ where id='amman-citadel';
update public.places set name_en=$t$Madaba$t$, description_en=$t$The center of Madaba Governorate in central Jordan, about 30 km southwest of Amman. The floor of the Greek Orthodox Church of Saint George (the Map Church) preserves a 6th-century mosaic map of the Holy Land, with the oldest surviving Byzantine depiction of Jerusalem. The city is famous for its Byzantine and Umayyad mosaics.$t$, region_name_en=$t$Madaba$t$ where id='madaba';
update public.places set name_en=$t$Ajloun Castle$t$, description_en=$t$A 12th-century Islamic castle on a hilltop in Jabal Auf in northwestern Jordan. Built by the Ayyubids, it was rebuilt as a castle in 1184 by Izz al-Din Usama, one of Saladin's commanders, and expanded by the Mamluk Aybak ibn Abdullah in 1214–1215.$t$, region_name_en=$t$Ajloun$t$ where id='ajloun-castle';
update public.places set name_en=$t$Mount Nebo$t$, description_en=$t$A mountain in Madaba Governorate about 700 meters above sea level, part of the Abarim range. In the Bible it is linked to Moses ascending it, seeing the land of Canaan and dying there. On its summit is a Byzantine memorial church built in the second half of the 4th century; a new protective canopy over it was reopened on 15 October 2016. It was visited by Pope John Paul II in 2000 and Pope Benedict XVI in 2009.$t$, region_name_en=$t$Madaba$t$ where id='mount-nebo';
update public.places set name_en=$t$Karak Castle$t$, description_en=$t$A medieval castle in the city of Karak and one of the largest castles in the Levant. Construction began in the 1140s (1142) during the reign of Fulk, King of Jerusalem.$t$, region_name_en=$t$Karak$t$ where id='karak-castle';
update public.places set name_en=$t$Umm Qais (Gadara)$t$, description_en=$t$A town in the far northwest of Jordan in Irbid Governorate, near the ruins of the ancient city of Gadara, a Greek cultural center in the Hellenistic and Roman periods and a member of the Decapolis. The site overlooks the Sea of Galilee, the Golan Heights and the Yarmouk Gorge, and includes the Rousan House, now a visitor center and museum displaying Greek statues and Christian mosaics.$t$, region_name_en=$t$Irbid$t$ where id='umm-qais';
update public.places set name_en=$t$Dana Biosphere Reserve$t$, description_en=$t$A reserve in south-central Jordan, nearest to the city of Tafilah, covering 308 km². Established in 1989 and managed by the Royal Society for the Conservation of Nature, it descends from about 1,500 meters at the Qadisiyah plateau to the Wadi Araba desert. It hosts 703 plant species, 215 bird species and 38 mammal species, including the Nubian ibex and the sand cat, along with archaeological and cultural heritage and its indigenous inhabitants, the Ata'ata.$t$, region_name_en=$t$Tafilah$t$ where id='dana-biosphere-reserve';
update public.places set name_en=$t$Civil Status and Passports Department$t$, description_en=$t$The government body responsible for issuing passports and the smart civil status ID, and registering births, marriages, deaths and family books. Its website offers online services such as first-time passport issuance, renewal and online account registration.$t$, region_name_en=$t$Amman$t$ where id='civil-status-passports-department';
update public.places set name_en=$t$Social Security Corporation$t$, description_en=$t$A general, solidarity-based social insurance system that protects individuals socially and economically; the law defines its benefits and funding sources, and benefits are funded by contributions from insured persons and employers. Its website offers services for individuals such as lump sum, unemployment, old-age pension, early retirement, maternity, work injuries, inquiring about the insurance number, account statements and online payment, and services for establishments such as registration, wage amendments and official letters, plus a jobs portal.$t$, region_name_en=null where id='social-security-corporation';
update public.places set name_en=$t$Ministry of Health (Jordan)$t$, description_en=$t$The ministry's official website. It offers online services for practicing health professions, booking and checking medical examination appointments for expatriates, a services and forms guide, and services such as yellow fever vaccination, ambulance and emergency cards, health certificates for craft workers and swimming pool licenses, plus directories of hospitals, pharmacies and health centers and a health map, with Android and iPhone apps.$t$, region_name_en=null where id='ministry-of-health';
update public.places set name_en=$t$Ministry of Labour (Jordan)$t$, description_en=$t$The ministry's official website, covering labor market regulation, legislation, funding programs and agreements. Its services include the "Himaya" platform for labor complaints, the national employment platform "Sajjil", services for non-Jordanian workers, a work permits portal, an inspection and occupational safety and health portal, licensing applications for private employment offices, reporting child labor, and online payment.$t$, region_name_en=null where id='ministry-of-labour';
update public.places set name_en=$t$Greater Amman Municipality$t$, description_en=$t$The e-services portal of Greater Amman Municipality. Its services include checking, paying and objecting to traffic violations, building and land tax, registering rental contracts, building and professional licenses, demolition and excavation permits, burial permits, submitting complaints, online payment and a services guide.$t$, region_name_en=$t$Amman$t$ where id='greater-amman-municipality';
update public.places set name_en=$t$Jordan University of Science and Technology$t$, description_en=$t$A public university in Irbid. Its website presents the vision, mission, strategic plan and regulations, and thirteen colleges and institutes including Engineering, Medicine, Pharmacy, Agriculture, Information Technology and Graduate Studies, along with deanships, research centers, student services, admission, the Centennial Library and alumni services, and announced new programs including cybersecurity, artificial intelligence and digital agriculture.$t$, region_name_en=$t$Irbid$t$ where id='just-university';
update public.places set name_en=$t$Jordan Tourism Board – Visit Jordan$t$, description_en=$t$The official website of the Jordan Tourism Board (Visit Jordan) promoting tourism in Jordan. It is available in several languages including Arabic, English, German, French, Spanish, Italian, Japanese, Russian and Chinese.$t$, region_name_en=null where id='visit-jordan-tourism-board';
update public.places set name_en=$t$Shobak Castle$t$, description_en=$t$A castle built by the Crusaders and expanded by the Mamluks, founded by Baldwin I, King of Jerusalem, in 1115 during a campaign to the region. It lies on the eastern side of Wadi Araba next to the town of Shobak, on a conical rocky mountain.$t$, region_name_en=$t$Ma'an$t$ where id='shobak-castle';
update public.places set name_en=$t$Pella (Tabaqat Fahl)$t$, description_en=$t$An archaeological city in northwestern Jordan in Irbid Governorate on the eastern slopes of the Jordan Valley, about 27 km south of the Sea of Galilee and about 130 km north of Amman. It was inhabited almost continuously from the Neolithic period through the Canaanite, Hellenistic, Roman, Byzantine and Islamic eras, and was one of the Decapolis cities. The site is government property managed by the Department of Antiquities, and only part of it has been excavated.$t$, region_name_en=$t$Irbid$t$ where id='pella-tabaqat-fahl';
update public.places set name_en=$t$Umm al-Jimal$t$, description_en=$t$A village in northern Jordan about 17 km east of Mafraq and less than 10 km from the Syrian border in the Hauran region, with the ruins of a Byzantine and early Islamic town built of volcanic basalt stone. The site dates from the Nabataean period to the Abbasid; it began in the 1st century CE, was abandoned around 900, and was resettled in the 20th century.$t$, region_name_en=$t$Mafraq$t$ where id='umm-al-jimal';
update public.places set name_en=$t$Wadi Mujib Nature Reserve$t$, description_en=$t$A river, narrow gorge and nature reserve east of the Dead Sea, about 90 km south of Amman. The wadi flows into the Dead Sea at about 420 meters below sea level, and the reserve rises to 1,277 meters in places. It was established by the Royal Society for the Conservation of Nature in 1987, declared a biosphere reserve by UNESCO in 2011, and covers 212 km².$t$, region_name_en=null where id='wadi-mujib';
update public.places set name_en=$t$Roman Theater in Amman$t$, description_en=$t$A Roman theater in Amman from the 2nd century CE; a Greek inscription indicates it was built in honor of Emperor Antoninus Pius (138–161 CE) when the city was called Philadelphia. It seats about 6,000 people and lies in east Amman at the foot of Jabal al-Joufa on a hill facing the Citadel hill.$t$, region_name_en=$t$Amman$t$ where id='amman-roman-theatre';
update public.places set name_en=$t$Dead Sea$t$, description_en=$t$A highly saline closed lake with no outlet, and the deepest hypersaline lake in the world. Its surface is about 440 meters below sea level (439.78 m in 2025), and its salinity is about 34.2%, roughly 9.6 times that of the ocean. It is bordered by Jordan on the east and the West Bank on the west, and its shores are the lowest dry land on Earth.$t$, region_name_en=null where id='dead-sea';
update public.places set name_en=$t$Aqaba$t$, description_en=$t$Jordan's only coastal city, in the far south at the northeastern tip of the Red Sea, the center of Aqaba Governorate and the largest city on the Gulf of Aqaba. Its port is the country's only seaport. It has more than thirty major dive sites suited to all levels, and fringing coral reefs extend over 25 km toward the Saudi border.$t$, region_name_en=$t$Aqaba$t$ where id='aqaba';
update public.places set name_en=$t$Azraq Wetland Reserve$t$, description_en=$t$A nature reserve in the town of Azraq in the eastern desert, described by Wikipedia as an oasis for migratory birds, and a Ramsar site since 10 January 1977. It was established by the Royal Society for the Conservation of Nature in 1978 and is still managed by it. About 280 migratory species have been recorded; its natural springs dried up in 1992 and most birds left, then the society partly restored the wetlands and several species returned.$t$, region_name_en=$t$Zarqa$t$ where id='azraq-wetland-reserve';
update public.places set name_en=$t$Machaerus (Mukawir) Fortress$t$, description_en=$t$A desert palace and fortress on a hilltop in the village of Mukawir in Madaba Governorate, overlooking the Dead Sea. It was built by the Hasmonean king Alexander Jannaeus around 90 BCE and destroyed by the Roman general Gabinius in 57 BCE, then rebuilt and expanded by Herod the Great. Accounts by Josephus and the New Testament say John the Baptist was imprisoned and beheaded there around 32 CE.$t$, region_name_en=$t$Madaba$t$ where id='machaerus-mukawir';
update public.places set name_en=$t$The Jordan Museum$t$, description_en=$t$The largest museum in Jordan, an art and archaeology museum officially opened in 2014 after construction began in 2009, in the Ras al-Ain district near downtown Amman. Its collection includes the Ain Ghazal statues, about 9,000 years old and among the oldest human statues, and the Dead Sea Scrolls including the Copper Scroll.$t$, region_name_en=$t$Amman$t$ where id='the-jordan-museum';
commit;
